// src/cli/options.ts
function parseInteger(value) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed)) {
    throw new Error(`Expected an integer, received ${value}`);
  }
  return parsed;
}
function parseNumber(value) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) {
    throw new Error(`Expected a number, received ${value}`);
  }
  return parsed;
}
function parseOutputOptions(options) {
  return {
    path: typeof options.output === "string" ? options.output : void 0,
    format: parseFormat(options.format),
    quality: typeof options.quality === "number" ? options.quality : void 0,
    omitBackground: Boolean(options.omitBackground)
  };
}
function parseRenderOptions(options) {
  return {
    selector: typeof options.selector === "string" ? options.selector : void 0,
    waitUntil: parseWaitUntil(options.waitUntil),
    delayMs: typeof options.delay === "number" ? options.delay : void 0
  };
}
function parseFormat(value) {
  if (value === void 0) return void 0;
  if (value === "png" || value === "jpeg") return value;
  throw new ClickClickError("INVALID_INPUT", "Format must be png or jpeg.");
}
function parseWaitUntil(value) {
  if (value === void 0) return void 0;
  if (value === "load" || value === "domcontentloaded" || value === "networkidle" || value === "commit") return value;
  throw new ClickClickError("INVALID_INPUT", "wait-until must be load, domcontentloaded, networkidle, or commit.");
}

